mapper.sql:
SELECT sbd.id, sbdd.id as detailId, sbd.code, sbd.source_id, sbd.dict_platform AS dictPlatform, sbd.shop_id, sbd.shop_name AS shopName, sbd.so_code AS soCode, sbd.status, sbd.picking_type AS pickingType, sbd.logistics_channel_id, sbd.logistics_channel_name AS logisticsChannelName, sbd.is_print_picking AS isPrintPicking, sbd.is_print_logistic AS isPrintLogistic, sbd.is_print_sku_barcode AS isPrintSkuBarcode, sbd.is_inspection AS isInspection, sbd.is_weigh AS isWeigh, sbd.weight AS weight, sbd.weight_unit AS weightUnit, sbdd.sku_id, sbdd.sku_no AS skuNo, sbdd.delivery_qty AS deliveryQty, sbdd.warehouse_id, sbdd.warehouse_name AS warehouseName, sbdd.warehouse_location AS warehouseLocation, sbd.create_time AS createTime, sbd.delivery_time AS deliveryTime, sbd.finish_print_time as finishPrintTime, sbd.inspection_time as inspectionTime, sbd.weighing_time as weighingTime, sbd.platform_code as platformCode, sbd.abnormal_cause as abnormalCause, sbd.shipment_mark, sbd.transfer_warehouse_ids FROM so_b2c_delivery sbd LEFT JOIN so_b2c_delivery_detail sbdd ON sbd.id = sbdd.main_id AND sbdd.is_deleted = FALSE WHERE ${params.sqlMap.default} AND sbd.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sbd.create_time desc
